def arr(frame) -> np.ndarray:
    return np.asarray(frame)


def color_counts(frame) -> Dict[int, int]:
    vals, cnts = np.unique(arr(frame), return_counts=True)
    return {int(v): int(c) for v, c in zip(vals, cnts)}


def connected_components(frame, colors: Optional[Iterable[int]] = None,
                         min_area: int = 1) -> List[Blob]:
    f = arr(frame)
    wanted = None if colors is None else {int(c) for c in colors}
    seen = np.zeros(f.shape, dtype=bool)
    out: List[Blob] = []
    rows, cols = f.shape[:2]
    for r in range(rows):
        for c in range(cols):
            if seen[r, c]:
                continue
            color = int(f[r, c])
            if wanted is not None and color not in wanted:
                seen[r, c] = True
                continue
            q = [(r, c)]
            seen[r, c] = True
            pts = []
            while q:
                x, y = q.pop()
                pts.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < rows and 0 <= ny < cols and not seen[nx, ny] and int(f[nx, ny]) == color:
                        seen[nx, ny] = True
                        q.append((nx, ny))
            if len(pts) >= min_area:
                rs = [p[0] for p in pts]
                cs = [p[1] for p in pts]
                out.append(Blob(color, (min(rs), min(cs), max(rs), max(cs)),
                                len(pts), (sum(rs) / len(pts), sum(cs) / len(pts))))
    return sorted(out, key=lambda b: (b.color, b.bbox))


def block_signatures(frame, cell: int = 4) -> Dict[Tuple[int, int], Tuple[int, ...]]:
    """Partition a frame into fixed cells and return each cell's color signature."""
    f = arr(frame)
    out = {}
    for r in range(0, f.shape[0], cell):
        for c in range(0, f.shape[1], cell):
            out[(r // cell, c // cell)] = tuple(int(v) for v in sorted(np.unique(f[r:r+cell, c:c+cell])))
    return out


def object_candidates(frame, cell: int = 4, min_area: int = 4) -> List[dict]:
    """A compact, game-agnostic object list from color components and cell signatures."""
    f = arr(frame)
    blobs = connected_components(f, min_area=min_area)
    sigs = block_signatures(f, cell)
    objects = []
    for b in blobs:
        r0, c0, r1, c1 = b.bbox
        objects.append({
            "color": b.color,
            "bbox": b.bbox,
            "top_left": b.top_left,
            "size": b.size,
            "area": b.area,
            "centroid": b.centroid,
            "cell": (r0 // cell, c0 // cell),
            "cell_sig": sigs.get((r0 // cell, c0 // cell)),
        })
    return objects


def bounded_replay_bfs(env, goal_fn, action_fn,
                       key_fn=None, max_states: int = 20000, max_depth: int = 80):
    """Path-only BFS for games whose deep Arena clones become expensive.

    The queue retains compact action paths, not recursively deep-copied runtime
    states. Each node is reconstructed from one root clone. ``action_fn(node)``
    may return integer actions or coordinate tuples such as ``(6, x, y)``.
    """
    if key_fn is None:
        key_fn = lambda e: arr(e.frame()).tobytes()

    def reconstruct(path):
        node = env.clone()
        for action in path:
            if isinstance(action, tuple):
                node.step(*action)
            else:
                node.step(int(action))
        return node

    start = reconstruct([])
    q = deque([[]])
    seen = {key_fn(start)}
    while q and len(seen) <= max_states:
        path = q.popleft()
        node = reconstruct(path)
        if goal_fn(node, path):
            return path
        if len(path) >= max_depth or node.terminal():
            continue
        for action in action_fn(node):
            child_path = path + [action]
            child = reconstruct(child_path)
            key = key_fn(child)
            if key in seen:
                continue
            seen.add(key)
            if goal_fn(child, child_path):
                return child_path
            q.append(child_path)
    return None


def level_goal(base_level: int):
    return lambda env, path: env.levels_completed > base_level

def _cell_shape(frame, i, j):
    """Centre colour and its area in one band cell.

    Shape distinguishes a small hazard from its expanded safe form even when
    both use the same colour.
    """
    r0, c0 = BAND * i, 13 + BAND * j
    color = int(frame[ROW_ANCHORS[i]][COL_ANCHORS[j]])
    area = sum(1 for r in range(r0, r0 + BAND)
               for c in range(c0, c0 + BAND)
               if int(frame[r][c]) == color)
    return color, area


def local_hazard_climb_search(env, max_expansions=600):
    """Search a timed climb using movement and only nearby interactions.

    Some towers use shape-changing hazards: interacting with a small hazard
    makes it safe to pass, while distant clicks merely waste the tight clock.
    The observational key retains each cell's shape as well as climbed height
    and elapsed moves.  Replaying paths from one root avoids retaining a large
    tree of nested clones.
    """
    base_level = env.levels_completed
    tie = itertools.count()
    root = env.clone()

    def key(node, height):
        frame = node.frame()
        return (height, moves_used(frame), avatar_column(frame),
                tuple(_cell_shape(frame, i, j)
                      for i in range(GRID_ROWS) for j in range(GRID_COLS)))

    def local_actions(node):
        frame = node.frame()
        col = avatar_column(frame)
        out = [(LEFT,), (RIGHT,)]
        if col is None:
            return out
        for i in (AVATAR_ROW - 1, AVATAR_ROW):
            for j in range(max(0, col - 1), min(GRID_COLS, col + 2)):
                color = int(frame[ROW_ANCHORS[i]][COL_ANCHORS[j]])
                if color not in OPEN_COLORS + WALL_COLORS + AVATAR_COLORS:
                    out.append(click_action(i, j))
        return out

    queue = [(0, 0, next(tie), 0, ())]
    seen = {key(root, 0)}
    for _ in range(max_expansions):
        if not queue:
            break
        _, _, _, height, path = heapq.heappop(queue)
        node = root.clone()
        run_actions(node, path)
        for action in local_actions(node):
            child = node.clone()
            child.step(*action)
            if child.levels_completed > base_level:
                return list(path + (action,))
            if child.terminal() or avatar_column(child.frame()) is None:
                continue
            gained = height + band_shift(node.frame(), child.frame())
            state = key(child, gained)
            if state in seen:
                continue
            seen.add(state)
            new_path = path + (action,)
            heapq.heappush(queue, (-gained, len(new_path), next(tie),
                                   gained, new_path))
    return []
def gravity_room_search(env, max_states=900, max_depth=48, debug=False):
    """Find a route through rooms controlled by gravity toggles and supports.

    Movement is always considered.  Global gravity toggles (colour 8) can
    change the whole room, while removable supports (14) are useful only when
    aligned with the avatar and shape-changing hazards (15) only when nearby.
    Reconstructing each state from one shallow root avoids chains of costly
    nested clones.
    """
    base_level = env.levels_completed
    root = env.clone()

    def avatar_cell(frame):
        for i, r in enumerate(ROW_ANCHORS):
            for j, c in enumerate(COL_ANCHORS):
                if int(frame[r][c]) in AVATAR_COLORS:
                    return i, j
        return None

    def choices(node):
        frame = node.frame()
        avatar = avatar_cell(frame)
        out = [(LEFT,), (RIGHT,)]
        if avatar is None:
            return out
        ai, aj = avatar
        for i, y in enumerate(ROW_ANCHORS):
            for j, x in enumerate(COL_ANCHORS):
                color = int(frame[y][x])
                if color == 8 and abs(j - aj) <= 1:
                    out.append((CLICK, x, y))
                elif color in (12, 14) and abs(j - aj) <= 1 and abs(i - ai) <= 1:
                    out.append((CLICK, x, y))
                elif color == 15 and abs(i - ai) <= 1 and abs(j - aj) <= 1:
                    out.append((CLICK, x, y))
        return out

    def state_key(node):
        frame = node.frame()
        cells = tuple(
            _cell_shape(frame, i, j)
            for i in range(GRID_ROWS)
            for j in range(GRID_COLS)
        )
        return cells, moves_used(frame) % 2

    def reconstruct(path):
        node = root.clone()
        run_actions(node, path)
        return node

    counter = itertools.count()
    frontier = [(0, 0, next(counter), ())]
    seen_progress = {state_key(root)}
    expanded = 0

    while frontier and expanded < max_states:
        neg_height, _, _, prefix = heapq.heappop(frontier)
        if debug:
            print("macro", -neg_height, len(prefix), expanded, len(frontier), prefix)
        stage = reconstruct(prefix)
        local_queue = deque([()])
        local_seen = {state_key(stage)}

        # Search the current room only until the camera rises.  Each distinct
        # landing becomes a macro successor, so unsafe early toggles can still
        # be backtracked without flattening the whole course into one BFS.
        while local_queue and expanded < max_states:
            suffix = local_queue.popleft()
            path = prefix + suffix
            node = stage.clone()
            run_actions(node, suffix)
            expanded += 1
            if len(path) >= max_depth or node.terminal():
                continue
            for action in choices(node):
                child = node.clone()
                child.step(*action)
                new_suffix = suffix + (action,)
                new_path = prefix + new_suffix
                if child.levels_completed > base_level:
                    return list(new_path)
                if child.terminal() or avatar_cell(child.frame()) is None:
                    continue
                key = state_key(child)
                gain = max(0, band_shift(node.frame(), child.frame()))
                if gain:
                    if key in seen_progress:
                        continue
                    seen_progress.add(key)
                    height = -neg_height + gain
                    heapq.heappush(
                        frontier,
                        (-height, len(new_path), next(counter), new_path),
                    )
                elif len(new_suffix) < 12 and key not in local_seen:
                    local_seen.add(key)
                    local_queue.append(new_suffix)
    return []


